import 'package:flutter/material.dart';
import '../../../core/routes/app_routes.dart';
import '../../../core/widgets/common_widgets.dart';
import '../../../data/repositories/photobook_repository.dart';
class OrderDetailScreen extends StatefulWidget {final String orderNumber; const OrderDetailScreen({super.key,required this.orderNumber}); @override State<OrderDetailScreen> createState()=>_OrderDetailScreenState();}
class _OrderDetailScreenState extends State<OrderDetailScreen>{final _repo=PhotobookRepository(); late Future<dynamic> _f; @override void initState(){super.initState(); _f=_repo.getOrderDetail(widget.orderNumber);} @override Widget build(BuildContext c)=>Scaffold(appBar:AppBar(title:const Text('Detail Pesanan')),body:FutureBuilder(future:_f,builder:(c,s){if(s.connectionState!=ConnectionState.done)return const LoadingState(); if(s.hasError)return ErrorState(message:s.error.toString(),onRetry:()=>setState(()=>_f=_repo.getOrderDetail(widget.orderNumber))); final o=s.data; return ListView(padding:const EdgeInsets.all(16),children:[Text(o.orderNumber),Text(o.productName),Text(o.designTitle),Text('Total: Rp ${o.totalAmount}'),Text(o.paymentStatus),Text(o.productionStatus),Text(o.shippingStatus),Text(o.finalPdfStatus),Text('print_file_ready: ${o.printFileReady}'),Text('jnt_awb: ${o.jntAwb??'-'}'),AppButton(label:'Tracking',onPressed:()=>Navigator.pushNamed(c,AppRoutes.orderTracking,arguments:o.orderNumber))]);}));}
